// Ported from the Node app's Sequelize model Setting (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class SettingConfiguration : IEntityTypeConfiguration<Setting>
{
    public void Configure(EntityTypeBuilder<Setting> builder)
    {
        builder.ToTable("settings");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Key);
        builder.Property(e => e.Key).HasColumnName("key").HasColumnType("nvarchar(60)").HasMaxLength(60).IsRequired();
        builder.Property(e => e.Value).HasColumnName("value").HasColumnType("nvarchar(max)").IsRequired();
        builder.Property(e => e.UpdatedByName).HasColumnName("updated_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.UpdatedAt).HasColumnName("updated_at").HasColumnType("datetime2");
    }
}
